css:
body :where([data-bz-node="pb"]) .bz-block{padding:0}
body :where([data-bz-node="pb"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="pb"]>.bz-container{padding-inline:0}

body [data-bz-node="pb"]{position:relative;overflow:hidden;min-height:520px;display:flex;flex-direction:column;justify-content:center;background:#16130f;padding:110px 0 70px}
body [data-bz-node="pb"]::after{content:"";position:absolute;inset:0;background:rgba(0,0,0,.62);z-index:1;pointer-events:none}
body [data-bz-node="pb"]>.bz-container{max-width:var(--container)}
body [data-bz-node="pb-img"]{position:absolute;inset:0;z-index:0}
body [data-bz-node="pb-img"] figure{margin:0;height:100%}
body [data-bz-node="pb-img"] img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 62%;border-radius:0}
body [data-bz-node="pb-row"]{display:block;position:relative;z-index:2;text-align:center}
body [data-bz-node="pb-crumb"] p{font:700 10.5px/1.4 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:#fff;margin:0 0 24px}
body [data-bz-node="pb-crumb"] a{color:#fff;text-decoration:none}
body [data-bz-node="pb-crumb"] a:hover{text-decoration:underline}
body [data-bz-node="pb-h"] .bz-headingblock{text-align:center}
body [data-bz-node="pb-h"] h1{font:700 46px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:#fff;margin:0 auto;max-width:900px}
body [data-bz-node="pb-sub"] .bz-text{max-width:640px;margin:24px auto 0}
body [data-bz-node="pb-sub"] p{font:400 14.5px/1.7 var(--font-body);color:rgba(255,255,255,.92);margin:0}
body [data-bz-node="pb-cta"]{margin-top:30px}
body [data-bz-node="pb-cta"] .bz-btns{margin:0;justify-content:center}
body [data-bz-node="pb-cta"] .bz-btn{display:inline-flex;align-items:center;justify-content:center;height:44px;padding:0 24px;border:0;border-radius:3px;background:#fff;color:var(--ink);font:700 10.5px/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;text-decoration:none}
body [data-bz-node="pb-cta"] .bz-btn:hover{background:#ececec}
@media (max-width:1100px){body [data-bz-node="pb"]{padding:100px 24px 56px;min-height:460px}body [data-bz-node="pb-h"] h1{font-size:38px}}
@media (max-width:640px){body [data-bz-node="pb"]{padding:92px 20px 44px;min-height:420px}body [data-bz-node="pb-h"] h1{font-size:28px}body [data-bz-node="pb-sub"] p{font-size:13.5px}body [data-bz-node="pb-crumb"] p{margin-bottom:18px}}
